def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Example:

    >>>@cached
    def expensive_function(x):
        return x**2

    >>> expensive_function(2)
    4

    >>> expensive_function(2)
    4

    """

    def wrapper(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
            if key in cache:
                return cache[key]
            else:
                value = f(*args, **kwargs)
                if lock:
                    with lock:
                        cache[key] = value
                return value

        return wrapped

    return wrapper

