    observer_schema = {}

    # Identifying fields
    if "apiVersion" in manifest_dict and manifest_dict["apiVersion"]:
        observer_schema["apiVersion"] = manifest_dict["apiVersion"]
    if "kind" in manifest_dict and manifest_dict["kind"]:
        observer_schema["kind"] = manifest_dict["kind"]

    if first_level:
        if "metadata" in manifest_dict and "name" in manifest_dict["metadata"]:
            observer_schema["name"] = manifest_dict["metadata"]["name"]
        if "metadata" in manifest_dict and "namespace" in manifest_dict["metadata"]:
            observer_schema["namespace"] = manifest_dict["metadata"]["namespace"]

    # Recursive processing of nested dictionaries
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
        else:
            # Replace non-list and non-dict values with None
            observer_schema[key] = None

    return observer_schema

