    # Iterate through the versions and add the inventory to the list
    for version in version_dirs:
        inventory = self.find_inventory(version)
        inventories.append(inventory)

        # Also check the content digests of each inventory
        content_digests = self.find_inventory_content_digests(inventory)
        for digest in content_digests:
            digests_to_check.add(digest)

    # Check if we have an inventory for every version
    if len(inventories) != len(version_dirs):
        raise Exception("Inventories are missing for some versions")

    # Check if the content digests are the same as those in the root inventory
    root_digests = self.find_inventory_content_digests(self.root_inventory)
    for digest in digests_to_check:
        if digest not in root_digests:
