def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise TypeError("Number must be an integer.")

    if not alphabet or not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("Alphabet must be a non-empty list with at least two elements.")

    if padding and not isinstance(padding, int):
        raise TypeError("Padding must be an integer or None.")

    if number < 0:
        raise ValueError("Number must be non-negative.")

    if padding is not None and padding < 0:
        raise ValueError("Padding must be a non-negative integer or None.")

    # Convert the number to a list of digits
    digits = []
    while number > 0:
        digits.append(number % 10)
        number //= 10

    # Pad the list of digits with leading zeros if necessary
    if padding:
        while len(digits) < padding:
            digits.insert(0, 0)

    # Convert each digit to its corresponding character in the alphabet
    result = ""
    for digit in digits:
        result += alphabet[digit]

    return result

