def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    if not callable(func):
        raise ValueError("func must be a callable function")
    if not isinstance(args, (list, tuple)):
        raise ValueError("args must be a list or tuple")
    if not isinstance(extra_env, dict):
        raise ValueError("extra_env must be a dictionary")
    if not all(isinstance(item, str) for item in args):
        raise ValueError("all items in args must be strings")
    if not all(isinstance(item, str) for item in extra_env.values()):
        raise ValueError("all values in extra_env must be strings")

    command_args = [func.__module__ + ":" + func.__qualname__]
    command_args.extend(args)

    env = os.environ.copy()
    if extra_env is not None:
        env.update(extra_env)

    try:
        result = subprocess.run(command_args, capture_output=True, env=env, timeout=timeout)
        return (result.returncode, result.stdout, result.stderr)
    except subprocess.TimeoutExpired:
        return (1, b"", b"")
    except Exception as e:
        return (1, b"", str(e).encode("utf-8"))

