    if not (0 <= ticks < 86400000000000):
        raise ValueError("Invalid ticks value: {}".format(ticks))

    seconds = ticks // 1000000000
    milliseconds = (ticks // 10000) % 1000

    hour, minute, second = divmod(seconds, 3600)
    minute, second = divmod(minute, 60)

