def find_tags(text: str, replacer=None) -> Tuple[Set, str]:
    tags = set()
    original_text = text
    in_code = False
    prev_char = ""
    for char in text:
        if char == "`":
            in_code = not in_code
        if not in_code and char.isalpha():
            if prev_char.isalpha():
                break
            tag = char
            while text[i + 1:].startswith(tag):
                i += 1
                tag += text[i + 1]
            if replacer:
                tag = replacer(tag)
            tags.add(tag)
            prev_char = char
    if in_code:
        raise ValueError("Unmatched backtick in code block")
    return tags, original_text if not replacer else replaced_text

