def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    # Handle invalid inputs
    if not url:
        raise ValueError("URL must be a valid string")
    if data is None:
        raise ValueError("Data must be a valid dictionary, bytes, or file-like object")
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise ValueError("Timeout must be an integer or float")
    if method is not None and method.lower() not in ["post", "get", "put", "delete"]:
        raise ValueError("Method must be a valid HTTP method")

    # Handle potential runtime issues with exception-handling behavior
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        if response.status_code >= 400:
            raise RuntimeError(f"HTTP error {response.status_code}: {response.text}")
        return response.status_code, None
    except requests.exceptions.RequestException as e:
        return None, e.__class__

