def validate_from_content(cls, spec_content=None):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file
    :raise IRValidatorException: When mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Initialize an empty spec dictionary
    spec = {}

    # Check if spec content is provided
    if not spec_content:
        raise IRValidatorException("Spec content is missing")

    # Load the spec content as a dictionary
    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Spec content is not a valid YAML")

    # Check if mandatory fields are present in the spec
    if "metadata" not in spec or "name" not in spec["metadata"] or "version" not in spec["metadata"]:
        raise IRValidatorException("Spec is missing mandatory metadata")

    # Check if mandatory fields are present in the spec
    if "spec" not in spec or "config" not in spec["spec"] or "template" not in spec["spec"]["config"]:
        raise IRValidatorException("Spec is missing mandatory spec/config/template fields")

    # Check if the template is a dictionary
    if not isinstance(spec["spec"]["config"]["template"], dict):
        raise IRValidatorException("Template must be a dictionary")

    # Check if the template has mandatory fields
    if "parameters" not in spec["spec"]["config"]["template"]:
        raise IRValidatorException("Template is missing mandatory parameters field")

    # If we get to this point, the spec is valid
    return spec

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, 'r') as f:
            file_data = yaml.safe_load(f)
            for field in ['Name', 'Age', 'Gender']:
                if field not in file_data:
                    raise IRValidatorException(f'{field} is a mandatory field in the YAML file.')
